Fix this React 19 SSR hydration mismatch in Next.js 15:

```jsx
// src/components/Header.jsx
import { useState } from 'react';

export function Header({ user }) {
  const [theme] = useState(localStorage.getItem('theme') || 'dark');
  const [ts]    = useState(new Date().toLocaleTimeString());
  return <div>{theme} — {ts} — {user.name}</div>;
}
```

Error: Hydration failed because the initial UI does not match what was rendered on the server.
Stack: Error at checkIfWorkInProgress (react-dom.development.js:3477)

### Root Cause
`localStorage` is undefined on the server and `new Date()` produces different values between server and client render, causing React 19's strict hydration to throw.

### Patch
```diff
--- a/src/components/Header.jsx
+++ b/src/components/Header.jsx
@@ -1,7 +1,17 @@
-import { useState } from 'react';
+import { useState, useEffect } from 'react';

 export function Header({ user }) {
-  const [theme] = useState(localStorage.getItem('theme') || 'dark');
-  const [ts]    = useState(new Date().toLocaleTimeString());
-  return <div>{theme} — {ts} — {user.name}</div>;
+  const [mounted, setMounted] = useState(false);
+  const [theme,   setTheme]   = useState('dark');
+  const [ts,      setTs]      = useState('');
+
+  useEffect(() => {
+    setTheme(localStorage.getItem('theme') ?? 'dark');
+    setTs(new Date().toLocaleTimeString());
+    setMounted(true);
+  }, []);
+
+  if (!mounted) return <div aria-busy="true" className="animate-pulse">Loading…</div>;
+  return <div>{theme} — {ts} — {user.name}</div>;
 }
```

### Regression Test (Vitest + RTL)
```jsx
import { describe, it, expect, vi } from 'vitest';
import { render } from '@testing-library/react';
import { Header } from './Header';

vi.stubGlobal('localStorage', { getItem: vi.fn(() => 'light') });

describe('Header SSR guard', () => {
  it('renders loading state before hydration without throwing', () => {
    const { container } = render(<Header user={{ name: 'Ada' }} />);
    expect(container).toBeDefined();
  });
});
```

Fix PostgreSQL connection pool exhaustion in this Node.js webhook handler:

```javascript
// server/routes/webhook.js
import { dbPool } from '../db.js';

export async function handleWebhook(req, res) {
  const client = await dbPool.connect();
  await client.query('UPDATE users SET status = $1 WHERE id = $2',
    [req.body.status, req.body.userId]);
  client.release();
  res.status(200).json({ ok: true });
}
```

Error: Error: timeout expired waiting for an idle client
Reproduced after ~200 concurrent requests under siege load-test.

### Root Cause
When `client.query` throws (e.g., constraint violation, timeout), `client.release()` is never called. Each uncaught exception permanently leaks one connection from the pool, eventually exhausting it.

### Patch
```diff
--- a/server/routes/webhook.js
+++ b/server/routes/webhook.js
@@ -1,9 +1,17 @@
 import { dbPool } from '../db.js';

 export async function handleWebhook(req, res) {
   const client = await dbPool.connect();
-  await client.query('UPDATE users SET status = $1 WHERE id = $2',
-    [req.body.status, req.body.userId]);
-  client.release();
-  res.status(200).json({ ok: true });
+  try {
+    await client.query('BEGIN');
+    await client.query(
+      'UPDATE users SET status = $1 WHERE id = $2',
+      [req.body.status, req.body.userId]
+    );
+    await client.query('COMMIT');
+    return res.status(200).json({ ok: true });
+  } catch (err) {
+    await client.query('ROLLBACK');
+    console.error('[webhook] DB error, rolled back:', err.message);
+    return res.status(500).json({ error: 'DB write failed' });
+  } finally {
+    client.release();  // ALWAYS release, even on error
+  }
 }
```

### Regression Test (Jest)
```javascript
import { handleWebhook } from './webhook.js';
import { dbPool } from '../db.js';

it('releases client even when query throws', async () => {
  const mockRelease = jest.fn();
  const mockQuery   = jest.fn()
    .mockResolvedValueOnce({}) // BEGIN
    .mockRejectedValueOnce(new Error('constraint')) // UPDATE fails
    .mockResolvedValueOnce({}); // ROLLBACK
  jest.spyOn(dbPool, 'connect').mockResolvedValue({
    query: mockQuery, release: mockRelease
  });
  const req = { body: { status: 'active', userId: 1 } };
  const res = { status: jest.fn().mockReturnThis(), json: jest.fn() };
  await handleWebhook(req, res);
  expect(mockRelease).toHaveBeenCalledTimes(1);
  expect(res.status).toHaveBeenCalledWith(500);
});
```

Diagnose and fix this Go channel deadlock:

```go
// worker/pipeline.go
package worker

func ProcessBatch(items []string) []string {
    results := make(chan string)
    for _, item := range items {
        go func(v string) {
            results <- process(v)
        }(item)
    }
    out := []string{}
    for r := range results {
        out = append(out, r)
    }
    return out
}
```

Error: fatal error: all goroutines are asleep - deadlock!
goroutine 1 [chan receive]

### Root Cause
The `results` channel is never closed, so `for r := range results` blocks forever after all goroutines finish sending. Also, the unbuffered channel forces each goroutine to wait for the receiver — with many goroutines this creates head-of-line blocking.

### Patch
```diff
--- a/worker/pipeline.go
+++ b/worker/pipeline.go
@@ -1,14 +1,19 @@
 package worker

+import "sync"
+
 func ProcessBatch(items []string) []string {
-    results := make(chan string)
+    results := make(chan string, len(items)) // buffered: no blocking senders
+    var wg sync.WaitGroup
     for _, item := range items {
+        wg.Add(1)
         go func(v string) {
+            defer wg.Done()
             results <- process(v)
         }(item)
     }
+    // Close channel once ALL goroutines are done so range can terminate
+    go func() { wg.Wait(); close(results) }()
     out := []string{}
     for r := range results {
         out = append(out, r)
     }
     return out
 }
```

### Regression Test (Go testing)
```go
package worker_test

import (
    "testing"
    "github.com/dorvik/worker"
)

func TestProcessBatch_NoDeadlock(t *testing.T) {
    items := []string{"a", "b", "c", "d", "e"}
    done := make(chan struct{})
    go func() {
        out := worker.ProcessBatch(items)
        if len(out) != len(items) {
            t.Errorf("expected %d results, got %d", len(items), len(out))
        }
        close(done)
    }()
    select {
    case <-done: // pass
    case <-time.After(5 * time.Second):
        t.Fatal("deadlock: ProcessBatch did not return within 5s")
    }
}
```
